export const GenerateEndorsedCertRequest = {
  toJsonObject(input: GenerateEndorsedCertRequest): any {
    return {
      attestation: SnpEvidence.toJsonObject(input.attestation),
      encrypt: input.encrypt,
      sign: input.sign,
      data: input.data,
    };
  },
  fromJsonObject(input: any): GenerateEndorsedCertRequest {
    return {
      attestation: SnpEvidence.fromJsonObject(input.attestation),
      encrypt: input.encrypt as Encrypt,
      sign: input.sign as Sign,
      data: input.data,
    };
  },
} as const;

